        r = self.plain().split('\n')
        return strip_ansi(r[6]).strip() if len(r)>6 else ''
    def raw(self):
        try: return open(self.pipe,'rb').read()
        except OSError: return b''
    def close(self):
        sh("tmux","send-keys","-t",self.name,"Escape")
        time.sleep(0.6)
        sh("tmux","kill-server")
        time.sleep(0.3)

def lesson_of(s):
    return s.lesson_text()
