#!/usr/bin/env python3
"""Minimal ANSI terminal emulator + pty harness for testing ./executable."""
import os, pty, subprocess, select, time, re, sys, fcntl, termios, struct

ESC = re.compile(r'\x1b\[[0-9;?]*[a-zA-Z]')

class Screen:
    def __init__(self, w=100, h=30):
        self.w=w; self.h=h
        self.buf=[[(' ',()) for _ in range(w)] for _ in range(h)]
        self.cx=0; self.cy=0
        self.cur_style=()
        self.cur_visible=True
    def clear(self):
        self.buf=[[(' ',()) for _ in range(self.w)] for _ in range(self.h)]
    def put(self,ch):
        if self.cy>=self.h or self.cx>=self.w: return
        self.buf[self.cy][self.cx]=(ch,self.cur_style)
        self.cx+=1
    def feed(self,s):
        i=0
        while i < len(s):
            c=s[i]
            if c=='\x1b':
                m=ESC.match(s,i)
                if m:
                    seq=m.group(0); i=m.end()
                    self.csi(seq)
                    continue
                else:
                    i+=1; continue
            if c=='\r': self.cx=0; i+=1; continue
            if c=='\n': self.cy+=1; i+=1; continue
            if c=='\b': self.cx=max(0,self.cx-1); i+=1; continue
            self.put(c); i+=1
    def csi(self,seq):
        body=seq[2:-1]; fin=seq[-1]
        if fin=='H' or fin=='f':
            p=[int(x) if x else 1 for x in body.split(';')] if body else [1,1]
            while len(p)<2: p.append(1)
            self.cy=p[0]-1; self.cx=p[1]-1
        elif fin=='J':
            if body in ('','0','2'): self.clear()
        elif fin=='h':
            if body=='?25': self.cur_visible=True
        elif fin=='l':
            if body=='?25': self.cur_visible=False
        elif fin=='m':
            self.sgr(body)
    def sgr(self,body):
        codes=[int(x) if x else 0 for x in body.split(';')] if body else [0]
        st=list(self.cur_style)
        i=0
        while i<len(codes):
            c=codes[i]
            if c==0: st=[]
            elif c==1: st.append('bold')
            elif c==2: st.append('dim')
            elif c==3: st.append('italic')
            elif c==4: st.append('underline')
            elif c==22: st=[x for x in st if x not in ('bold','dim')]
            elif c==23: st=[x for x in st if x!='italic']
            elif c==24: st=[x for x in st if x!='underline']
            elif c==39: st=[x for x in st if not x.startswith('fg')]
            elif c==49: st=[x for x in st if not x.startswith('bg')]
            elif c==59: st=[x for x in st if not x.startswith('ul')]
            elif 30<=c<=37: st.append('fg%d'%(c-30))
            elif 40<=c<=47: st.append('bg%d'%(c-40))
            elif 90<=c<=97: st.append('fg%d'%(c-90+8))
            elif 100<=c<=107: st.append('bg%d'%(c-100+8))
            elif c==38 or c==48 or c==58:
                pre='fg' if c==38 else ('bg' if c==48 else 'ul')
                if i+1<len(codes) and codes[i+1]==5:
                    st.append('%s%d'%(pre,codes[i+2])); i+=2
                elif i+1<len(codes) and codes[i+1]==2:
                    st.append('%s%d,%d,%d'%(pre,codes[i+2],codes[i+3],codes[i+4])); i+=4
            i+=1
        self.cur_style=tuple(st)
    def text(self):
        return ['' .join(c for c,s in row) for row in self.buf]
    def plain_row(self,i):
        return ''.join(c for c,s in self.buf[i])

class App:
    def __init__(self, args, w=100, h=30, binary='./executable', cwd=None):
        self.w=w; self.h=h
        self.master, self.slave = pty.openpty()
        fcntl.ioctl(self.slave, termios.TIOCSWINSZ, struct.pack('HHHH', h, w, 0, 0))
        env=dict(os.environ); env['TERM']='xterm-256color'
        env['COLUMNS']=str(w); env['LINES']=str(h)
        self.p = subprocess.Popen([binary]+list(args), stdin=self.slave, stdout=self.slave,
                                  stderr=subprocess.PIPE, cwd=cwd, env=env, close_fds=True)
        os.close(self.slave)
        self.screen=Screen(w,h)
        self.raw=b''
        self.dead=False
    def pump(self, t=0.05):
        r,_,_=select.select([self.master],[],[],t)
        got=b''
        while r:
            try:
                d=os.read(self.master,65536)
            except OSError:
                self.dead=True; break
            if not d: self.dead=True; break
            got+=d
            r,_,_=select.select([self.master],[],[],0.005)
        if got:
            s=got.decode('utf8','replace')
            self.raw+=got
            self.screen.feed(s)
        return got
    def wait(self, t=0.5):
        end=time.time()+t
        while time.time()<end:
            self.pump(0.02)
    def send(self, s, delay=0.0):
        os.write(self.master, s.encode('utf8'))
        if delay: time.sleep(delay)
    def rows(self):
        return self.screen.text()
    def close(self):
        try: self.p.terminate()
        except Exception: pass
        try: self.p.wait(timeout=1)
        except Exception: pass
        try: os.close(self.master)
        except Exception: pass
        try:
            err=self.p.stderr.read()
        except Exception:
            err=b''
        return err
