#!/usr/bin/env python3
import sys, time, collections, threading, json, math, queue
sys.path.insert(0,'/tmp/h')
from term import App

C = {'2':25,'3':19,'4':15,'w':10}

def samples(narg,c,top,n,out,tid):
    """produce `n` runs at level top, returning list of item-sets"""
    res=[]
    for i in range(n):
        try:
            a=App(['-n',narg,'-c',str(c),'-r','1','-t',str(top),'-w','1','-a','0'])
            a.wait(0.16)
            row=a.rows()[6][1:78]
            a.close()
            toks=row.split()
            if len(toks)==c:
                res.append(set(toks))
        except Exception:
            pass
    out[tid]=res

def get_runs(narg,c,top,nruns,nt=10):
    out=[None]*nt
    per=nruns//nt
    ts=[]
    for t in range(nt):
        th=threading.Thread(target=samples,args=(narg,c,top,per,out,t)); th.start(); ts.append(th)
    for th in ts: th.join()
    res=[]
    for o in out:
        if o: res.extend(o)
    return res

def walk(narg, factor=10.0):
    c=C[narg]
    known=set(); order=[]
    fails=[]
    t0=time.time()
    for k in range(1,201):
        want=max(2, int(math.ceil(factor*k/c)))
        got=0; found=None
        while got < want:
            runs=get_runs(narg,c,k,min(40, want-got))
            got+=len(runs)
            for s in runs:
                new = s - known
                if new:
                    if len(new)==1:
                        found=list(new)[0]
                    else:
                        found=('AMBIG',new)
                    break
