//! Low level terminal handling: syscalls, raw mode, window size and input parsing.
//!
//! Everything is implemented with raw linux syscalls (x86_64) so that the
//! binary has no external dependencies.

use std::io;

// ---------------------------------------------------------------------------
// raw syscalls
// ---------------------------------------------------------------------------

#[cfg(all(target_arch = "x86_64", target_os = "linux"))]
#[inline]
unsafe fn sys_syscall3(n: usize, a1: usize, a2: usize, a3: usize) -> isize {
    let ret: isize;
    core::arch::asm!(
        "syscall",
        inlateout("rax") n => ret,
        in("rdi") a1,
        in("rsi") a2,
        in("rdx") a3,
        lateout("rcx") _,
        lateout("r11") _,
        options(nostack)
    );
    ret
}

#[cfg(all(target_arch = "x86_64", target_os = "linux"))]
#[inline]
unsafe fn sys_syscall1(n: usize, a1: usize) -> isize {
    let ret: isize;
    core::arch::asm!(
        "syscall",
        inlateout("rax") n => ret,
        in("rdi") a1,
        lateout("rcx") _,
        lateout("r11") _,
        options(nostack)
    );
    ret
}

#[cfg(not(all(target_arch = "x86_64", target_os = "linux")))]
unsafe fn sys_syscall3(_: usize, _: usize, _: usize, _: usize) -> isize {
    -1
}
#[cfg(not(all(target_arch = "x86_64", target_os = "linux")))]
unsafe fn sys_syscall1(_: usize, _: usize) -> isize {
    -1
}

const SYS_READ: usize = 0;
const SYS_WRITE: usize = 1;
const SYS_OPEN: usize = 2;
const SYS_CLOSE: usize = 3;
const SYS_POLL: usize = 7;
const SYS_IOCTL: usize = 16;

// ioctl requests
const TCGETS: usize = 0x5401;
const TCSETS: usize = 0x5402;
const TIOCGWINSZ: usize = 0x5413;

// termios flag bits (linux)
const IGNBRK: u32 = 0o000001;
const BRKINT: u32 = 0o000002;
const PARMRK: u32 = 0o000010;
const ISTRIP: u32 = 0o000040;
const INLCR: u32 = 0o000100;
const IGNCR: u32 = 0o000200;
const ICRNL: u32 = 0o000400;
const IXON: u32 = 0o002000;
const IXOFF: u32 = 0o010000;
const OPOST: u32 = 0o000001;
const CSIZE: u32 = 0o000060;
const PARENB: u32 = 0o000400;
const CS8: u32 = 0o000060;
const ISIG: u32 = 0o000001;
const ICANON: u32 = 0o000002;
const ECHO: u32 = 0o000010;
const ECHONL: u32 = 0o000100;
const IEXTEN: u32 = 0o100000;

const VMIN: usize = 6;
const VTIME: usize = 5;

const O_RDONLY: usize = 0;

/// struct termios as laid out by linux on x86_64 (60 bytes)
#[repr(C)]
#[derive(Clone, Copy)]
pub struct Termios {
    c_iflag: u32,
    c_oflag: u32,
    c_cflag: u32,
    c_lflag: u32,
    c_line: u8,
    c_cc: [u8; 32],
    c_ispeed: u32,
    c_ospeed: u32,
}

impl Termios {
    fn zeroed() -> Termios {
        Termios {
            c_iflag: 0,
            c_oflag: 0,
            c_cflag: 0,
            c_lflag: 0,
            c_line: 0,
            c_cc: [0; 32],
            c_ispeed: 0,
            c_ospeed: 0,
        }
    }
}

#[repr(C)]
#[derive(Clone, Copy)]
struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

#[repr(C)]
#[derive(Clone, Copy)]
struct PollFd {
    fd: i32,
    events: i16,
    revents: i16,
}

const POLLIN: i16 = 0x001;

fn errno() -> i32 {
    unsafe {
        let mut tls: usize;
        core::arch::asm!("mov {}, gs:0x0", out(reg) tls, options(nostack, preserves_flags));
        let e = *((tls - 4) as *const i32);
        e
    }
}

fn last_error() -> io::Error {
    let e = errno();
    if e == 0 {
        io::Error::from_raw_os_error(6)
    } else {
        io::Error::from_raw_os_error(e)
    }
}

// ---------------------------------------------------------------------------
// file descriptor helpers
// ---------------------------------------------------------------------------

struct Fd {
    fd: i32,
    owned: bool,
}

impl Fd {
    fn open_dev_tty() -> io::Result<Fd> {
        let path = b"/dev/tty\0";
        let r = unsafe { sys_syscall3(SYS_OPEN, path.as_ptr() as usize, O_RDONLY, 0) };
        if r < 0 {
            Err(last_error())
        } else {
            Ok(Fd { fd: r as i32, owned: true })
        }
    }
    /// crossterm style: use stdin when it is a tty, otherwise /dev/tty
    fn tty_for_termios() -> io::Result<Fd> {
        let mut t = Termios::zeroed();
        let r = unsafe {
            sys_syscall3(SYS_IOCTL, 0usize, TCGETS, &mut t as *mut Termios as usize)
        };
        if r == 0 {
            Ok(Fd { fd: 0, owned: false })
        } else {
            Fd::open_dev_tty()
        }
    }
}

impl Drop for Fd {
    fn drop(&mut self) {
        if self.owned {
            unsafe {
                sys_syscall1(SYS_CLOSE, self.fd as usize);
            }
        }
    }
}

// ---------------------------------------------------------------------------
// raw mode
// ---------------------------------------------------------------------------

static mut SAVED: Option<Termios> = None;
static mut SAVED_FD: i32 = -1;
static mut RAW: bool = false;

fn get_termios(fd: i32) -> io::Result<Termios> {
    let mut t = Termios::zeroed();
    let r = unsafe { sys_syscall3(SYS_IOCTL, fd as usize, TCGETS, &mut t as *mut Termios as usize) };
    if r < 0 {
        Err(last_error())
    } else {
        Ok(t)
    }
}

fn set_termios(fd: i32, t: &Termios) -> io::Result<()> {
    let r = unsafe { sys_syscall3(SYS_IOCTL, fd as usize, TCSETS, t as *const Termios as usize) };
    if r < 0 {
        Err(last_error())
    } else {
        Ok(())
    }
}

fn raw_terminal_attr(t: &mut Termios) {
    t.c_iflag &= !(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON | IXOFF);
    t.c_oflag &= !OPOST;
    t.c_lflag &= !(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    t.c_cflag &= !(CSIZE | PARENB);
    t.c_cflag |= CS8;
    t.c_cc[VMIN] = 1;
