        .file_name()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_else(|| argv0.to_string())
}

pub fn parse() -> Config {
    let mut argv = std::env::args();
    let argv0 = argv.next().unwrap_or_else(|| "ngrrram".to_string());
