            let body = &a[2..];
            let (name, inline) = match body.find('=') {
                Some(k) => (&body[..k], Some(body[k + 1..].to_string())),
                None => (body, None),
            };
            if name.is_empty() {
                err_exit(format!(
                    "error: unexpected argument '--' found\n\n{}",
                    usage_options(&bin)
                ));
            }
            match find_long(name) {
                Some(k) => {
                    let o = &OPTS[k];
                    if o.long == "help" {
                        if inline.is_some() {
                            err_exit(format!(
                                "error: unexpected value '{}' for '--help' found; no more were expected\n\nUsage: {} --help\n\nFor more information, try '--help'.\n",
                                inline.unwrap(), bin));
