                        Some(_) => {
                            if p.seen[k] {
                                err_exit(format!(
                                    "error: the argument '{}' cannot be used multiple times\n\n{}",
                                    id_of(o),
                                    usage_options(&bin)
                                ));
                            }
                            let v = match inline {
                                Some(v) => v,
                                None => {
                                    i += 1;
                                    if i >= args.len() {
                                        err_exit(format!(
                                            "error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.\n",
                                            id_of(o)));
                                    }
                                    args[i].clone()
                                }
                            };
                            p.vals[k] = Some(v);
                            p.seen[k] = true;
                        }
                        None => {
                            if let Some(v) = inline {
                                err_exit(format!(
                                    "error: unexpected value '{}' for '--{}' found; no more were expected\n\nUsage: {} --{}\n\nFor more information, try '--help'.\n",
                                    v, o.long, bin, o.long));
                            }
                            if p.seen[k] {
                                err_exit(format!(
                                    "error: the argument '--{}' cannot be used multiple times\n\n{}",
                                    o.long,
                                    usage_options(&bin)
                                ));
                            }
                            p.seen[k] = true;
                        }
                    }
