                                            "error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.\n",
                                            id_of(o)));
                                    }
                                    args[i].clone()
                                };
                                p.vals[k] = Some(v);
                                p.seen[k] = true;
                                ci = chars.len();
                            }
                            None => {
                                if p.seen[k] {
                                    err_exit(format!(
                                        "error: the argument '--{}' cannot be used multiple times\n\n{}",
                                        o.long,
                                        usage_options(&bin)
                                    ));
                                }
                                p.seen[k] = true;
                                ci += 1;
                            }
                        }
                    }
                    None => {
                        err_exit(format!(
                            "error: unexpected argument '-{}' found\n\n{}",
                            c,
                            usage_options(&bin)
                        ));
                    }
                }
            }
            i += 1;
            continue;
        }
        err_exit(format!(
            "error: unexpected argument '{}' found\n\n{}",
            a,
            usage_options(&bin)
        ));
    }

    let get = |k: usize| p.vals[k].clone();
    let num = |k: usize, name: &str| -> i64 {
        let raw = get(k).unwrap_or_else(|| OPTS[k].default.unwrap_or("").to_string());
        match raw.parse::<i64>() {
            Ok(v) => {
                if v > 2147483647 || v < -2147483648 {
                    err_exit(format!(
                        "error: invalid value '{}' for '{}': {} is not in -2147483648..=2147483647\n\nFor more information, try '--help'.\n",
                        raw, id_of(&OPTS[k]), v));
                }
                v
            }
            Err(e) => {
                let reason = if raw.is_empty() {
                    "cannot parse integer from empty string".to_string()
                } else {
                    match e.kind() {
                        std::num::IntErrorKind::PosOverflow => {
                            "number too large to fit in target type".to_string()
                        }
                        std::num::IntErrorKind::NegOverflow => {
                            "number too small to fit in target type".to_string()
                        }
                        _ => "invalid digit found in string".to_string(),
                    }
                };
                err_exit(format!(
                    "error: invalid value '{}' for '{}': {}\n\nFor more information, try '--help'.\n",
