        if min_bound > max_bound {
            continue;
        }
        for j in 0..b_len {
            if j < min_bound {
                continue;
            }
            if j > max_bound {
                break;
            }
            if a[i] == b[j] && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0)
            * ((matches / a_len as f64)
                + (matches / b_len as f64)
                + ((matches - transpositions) / matches))
    }
