//! Command line parsing that mirrors the clap based interface of the original
//! tool (including its error messages and help output).

use std::process::exit;

pub struct Config {
    pub n: String,
    pub top: i64,
    pub combi: i64,
    pub rep: i64,
    pub wpm: i64,
    pub acc: i64,
    pub emu_in: String,
    pub emu_out: String,
    pub show_ortho: bool,
    pub nokb: bool,
    pub cat: bool,
}

/// description of one option, used for help / error rendering
struct OptDef {
    short: Option<char>,
    long: &'static str,
    value_name: Option<&'static str>,
    help: &'static str,
    default: Option<&'static str>,
}

const OPTS: [OptDef; 12] = [
    OptDef { short: Some('n'), long: "n", value_name: Some("2|3|4|w|file"),
        help: "use bi-(2), tri-(3), tetragrams(4), (w)ords or comma separated wordlist file.",
        default: Some("2") },
    OptDef { short: Some('t'), long: "top", value_name: Some("1-200"),
        help: "use the top X ngrams ordered by usage.", default: Some("50") },
    OptDef { short: Some('c'), long: "combi", value_name: Some("1-200"),
        help: "how many different ngrams to use in a single lesson.", default: Some("2") },
    OptDef { short: Some('r'), long: "rep", value_name: Some("number"),
        help: "how often to repeat *each* different ngram in a lesson.", default: Some("3") },
    OptDef { short: Some('w'), long: "wpm", value_name: Some("number"),
        help: "the wpm threshold at which the lesson is considered a success.", default: Some("40") },
    OptDef { short: Some('a'), long: "acc", value_name: Some("0-100"),
        help: "the accuracy in percent at which the lesson is considered a success.",
        default: Some("94") },
    OptDef { short: None, long: "emu-in", value_name: Some("layout"),
        help: "your current keyboard layout. only needed if you want to emulate a different layout. see docs for supported layouts.",
        default: Some("") },
    OptDef { short: None, long: "emu-out", value_name: Some("layout"),
        help: "the layout you want to emulate. only needed if you want to emulate a different layout. see docs for supported layouts.",
        default: Some("") },
    OptDef { short: None, long: "show-ortho", value_name: None,
        help: "show keyboard in ortholinear format", default: None },
    OptDef { short: None, long: "nokb", value_name: None,
        help: "pass this flag to disable the keyboard layout display.", default: None },
    OptDef { short: None, long: "cat", value_name: None,
        help: "the most important flag. don't practice alone.", default: None },
    OptDef { short: Some('h'), long: "help", value_name: None,
        help: "Print help", default: None },
];

fn id_of(o: &OptDef) -> String {
    match o.value_name {
        Some(v) => format!("--{} <{}>", o.long, v),
        None => format!("--{}", o.long),
    }
}

fn help_line(o: &OptDef) -> String {
    let mut left = String::new();
    match o.short {
        Some(c) => {
            left.push_str("  -");
            left.push(c);
            left.push_str(", --");
        }
        None => left.push_str("      --"),
    }
    left.push_str(o.long);
    if let Some(v) = o.value_name {
        left.push_str(&format!(" <{}>", v));
    }
    let mut s = left.clone();
    while s.len() < 24 {
        s.push(' ');
    }
    s.push_str(o.help);
    if let Some(d) = o.default {
        s.push_str(&format!(" [default: {}]", d));
    }
    s
}

pub fn help_text(bin: &str) -> String {
    let mut s = format!("Usage: {} [OPTIONS]\n\nOptions:\n", bin);
    for o in OPTS.iter() {
        s.push_str(&help_line(o));
        s.push('\n');
    }
    s
}

fn err_exit(msg: String) -> ! {
    eprint!("{}", msg);
    exit(2)
}

fn usage_options(bin: &str) -> String {
    format!("Usage: {} [OPTIONS]\n\nFor more information, try '--help'.\n", bin)
}

fn usage_all_args(bin: &str) -> String {
    let parts: Vec<String> = OPTS.iter().map(|o| id_of(o)).collect();
    format!(
        "Usage: {} <{}>\n\nFor more information, try '--help'.\n",
        bin,
        parts.join("|")
    )
}

/// jaro similarity (strsim compatible)
fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let a_len = a.len();
    let b_len = b.len();
    if a_len == 0 && b_len == 0 {
        return 1.0;
    }
    if a_len == 0 || b_len == 0 {
        return 0.0;
    }
    if a_len == 1 && b_len == 1 {
        return if a[0] == b[0] { 1.0 } else { 0.0 };
    }
    let search_range = (std::cmp::max(a_len, b_len) / 2).saturating_sub(1);
    let mut b_consumed = vec![false; b_len];
    let mut matches = 0.0f64;
    let mut transpositions = 0.0f64;
    let mut b_match_index = 0usize;
    for i in 0..a_len {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = std::cmp::min(b_len - 1, i + search_range);
        if min_bound > max_bound {
            continue;
        }
        for j in 0..b_len {
            if j < min_bound {
                continue;
            }
            if j > max_bound {
                break;
            }
            if a[i] == b[j] && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0)
            * ((matches / a_len as f64)
                + (matches / b_len as f64)
                + ((matches - transpositions) / matches))
    }
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let jaro_distance = jaro(a, b);
    let prefix_length = a
        .chars()
        .zip(b.chars())
        .take_while(|(ac, bc)| ac == bc)
        .count()
        .min(4);
    let jaro_winkler_distance =
        jaro_distance + (0.1 * prefix_length as f64 * (1.0 - jaro_distance));
    if jaro_winkler_distance <= 1.0 {
        jaro_winkler_distance
    } else {
        1.0
    }
}

fn did_you_mean(arg: &str) -> Option<&'static str> {
    let mut best: Option<(f64, &'static str)> = None;
    for o in OPTS.iter() {
        let c = jaro_winkler(arg, o.long);
        if c > 0.7 {
            match best {
                Some((bc, _)) if bc > c => {}
                _ => best = Some((c, o.long)),
            }
        }
    }
    best.map(|(_, l)| l)
}

struct Parsed {
    vals: [Option<String>; 12],
    seen: [bool; 12],
}

fn find_long(name: &str) -> Option<usize> {
    OPTS.iter().position(|o| o.long == name)
}

fn find_short(c: char) -> Option<usize> {
    OPTS.iter().position(|o| o.short == Some(c))
}

fn bin_name(argv0: &str) -> String {
    std::path::Path::new(argv0)
        .file_name()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_else(|| argv0.to_string())
}

pub fn parse() -> Config {
    let mut argv = std::env::args();
    let argv0 = argv.next().unwrap_or_else(|| "ngrrram".to_string());
    let bin = bin_name(&argv0);
    let args: Vec<String> = argv.collect();

    let mut p = Parsed { vals: [None; 12], seen: [false; 12] };
    let mut i = 0usize;
    let mut only_positional = false;

    while i < args.len() {
        let a = args[i].clone();
        if only_positional {
            err_exit(format!(
                "error: unexpected argument '{}' found\n\n{}",
                a,
                usage_options(&bin)
            ));
        }
        if a == "--" {
            only_positional = true;
            i += 1;
            continue;
        }
        if a.starts_with("--") {
            let body = &a[2..];
            let (name, inline) = match body.find('=') {
                Some(k) => (&body[..k], Some(body[k + 1..].to_string())),
                None => (body, None),
            };
            if name.is_empty() {
                err_exit(format!(
                    "error: unexpected argument '--' found\n\n{}",
                    usage_options(&bin)
                ));
            }
            match find_long(name) {
                Some(k) => {
                    let o = &OPTS[k];
                    if o.long == "help" {
                        if inline.is_some() {
                            err_exit(format!(
                                "error: unexpected value '{}' for '--help' found; no more were expected\n\nUsage: {} --help\n\nFor more information, try '--help'.\n",
                                inline.unwrap(), bin));
                        }
                        print!("{}", help_text(&bin));
                        exit(0);
                    }
                    match o.value_name {
                        Some(_) => {
                            if p.seen[k] {
                                err_exit(format!(
                                    "error: the argument '{}' cannot be used multiple times\n\n{}",
                                    id_of(o),
                                    usage_options(&bin)
                                ));
                            }
                            let v = match inline {
                                Some(v) => v,
                                None => {
                                    i += 1;
                                    if i >= args.len() {
                                        err_exit(format!(
                                            "error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.\n",
                                            id_of(o)));
                                    }
                                    args[i].clone()
                                }
                            };
                            p.vals[k] = Some(v);
                            p.seen[k] = true;
                        }
                        None => {
                            if let Some(v) = inline {
                                err_exit(format!(
                                    "error: unexpected value '{}' for '--{}' found; no more were expected\n\nUsage: {} --{}\n\nFor more information, try '--help'.\n",
                                    v, o.long, bin, o.long));
                            }
                            if p.seen[k] {
                                err_exit(format!(
                                    "error: the argument '--{}' cannot be used multiple times\n\n{}",
                                    o.long,
                                    usage_options(&bin)
                                ));
                            }
                            p.seen[k] = true;
                        }
                    }
                }
                None => {
                    let msg = match did_you_mean(name) {
                        Some(s) => format!(
                            "error: unexpected argument '--{}' found\n\n  tip: a similar argument exists: '--{}'\n\n{}",
                            name, s, usage_all_args(&bin)
                        ),
                        None => format!(
                            "error: unexpected argument '--{}' found\n\n{}",
                            name,
                            usage_options(&bin)
                        ),
                    };
                    err_exit(msg);
                }
            }
            i += 1;
            continue;
        }
        if a.starts_with('-') && a.len() > 1 {
            let chars: Vec<char> = a[1..].chars().collect();
            let mut ci = 0usize;
            while ci < chars.len() {
                let c = chars[ci];
                match find_short(c) {
                    Some(k) => {
                        let o = &OPTS[k];
                        if o.long == "help" {
                            print!("{}", help_text(&bin));
                            exit(0);
                        }
                        match o.value_name {
                            Some(_) => {
                                if p.seen[k] {
                                    err_exit(format!(
                                        "error: the argument '{}' cannot be used multiple times\n\n{}",
                                        id_of(o),
                                        usage_options(&bin)
                                    ));
                                }
                                let rest: String = chars[ci + 1..].iter().collect();
                                let v = if !rest.is_empty() {
                                    let rest = if let Some(stripped) = rest.strip_prefix('=') {
                                        stripped.to_string()
                                    } else {
                                        rest
                                    };
                                    rest
                                } else {
                                    i += 1;
                                    if i >= args.len() {
                                        err_exit(format!(
                                            "error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.\n",
                                            id_of(o)));
                                    }
                                    args[i].clone()
                                };
                                p.vals[k] = Some(v);
                                p.seen[k] = true;
                                ci = chars.len();
                            }
                            None => {
                                if p.seen[k] {
                                    err_exit(format!(
                                        "error: the argument '--{}' cannot be used multiple times\n\n{}",
                                        o.long,
                                        usage_options(&bin)
                                    ));
                                }
                                p.seen[k] = true;
                                ci += 1;
                            }
                        }
                    }
                    None => {
                        err_exit(format!(
                            "error: unexpected argument '-{}' found\n\n{}",
                            c,
                            usage_options(&bin)
                        ));
                    }
                }
            }
            i += 1;
            continue;
        }
        err_exit(format!(
            "error: unexpected argument '{}' found\n\n{}",
            a,
            usage_options(&bin)
        ));
    }

    let get = |k: usize| p.vals[k].clone();
    let num = |k: usize, name: &str| -> i64 {
        let raw = get(k).unwrap_or_else(|| OPTS[k].default.unwrap_or("").to_string());
        match raw.parse::<i64>() {
            Ok(v) => {
                if v > 2147483647 || v < -2147483648 {
                    err_exit(format!(
                        "error: invalid value '{}' for '{}': {} is not in -2147483648..=2147483647\n\nFor more information, try '--help'.\n",
                        raw, id_of(&OPTS[k]), v));
                }
                v
            }
            Err(e) => {
                let reason = if raw.is_empty() {
                    "cannot parse integer from empty string".to_string()
                } else {
                    match e.kind() {
                        std::num::IntErrorKind::PosOverflow => {
                            "number too large to fit in target type".to_string()
                        }
                        std::num::IntErrorKind::NegOverflow => {
                            "number too small to fit in target type".to_string()
                        }
                        _ => "invalid digit found in string".to_string(),
                    }
                };
                err_exit(format!(
                    "error: invalid value '{}' for '{}': {}\n\nFor more information, try '--help'.\n",
                    raw,
                    id_of(&OPTS[k]),
                    reason
                ))
            }
        }
    };

    let top = num(1, "top");
    let combi = num(2, "combi");
    let rep = num(3, "rep");
    let wpm = num(4, "wpm");
    let acc = num(5, "acc");

    if !(1..=200).contains(&top) {
        println!("Invalid argument for top. Use a number between 1 and 200.");
        exit(1);
    }
    if !(1..=200).contains(&combi) {
        println!("Invalid argument for combi. Use a number between 1 and 200.");
        exit(1);
    }
    if rep < 1 {
        println!("Invalid argument for rep. Use a number between 1 and 200.");
        exit(1);
    }
    if !(1..=200).contains(&wpm) {
        println!("Invalid argument for wpm. Use a number between 1 and 200.");
        exit(1);
    }
    if !(0..=100).contains(&acc) {
        println!("Invalid argument for acc. Use a number between 0 and 100.");
        exit(1);
    }

    let emu_in = get(6).unwrap_or_default();
    let emu_out = get(7).unwrap_or_default();

    Config {
        n: get(0).unwrap_or_else(|| "2".to_string()),
        top,
        combi,
        rep,
        wpm,
        acc,
        emu_in,
        emu_out,
        show_ortho: p.seen[8],
        nokb: p.seen[9],
        cat: p.seen[10],
    }
}
RSEOF
echo ok; wc -l src/args.rs"}

{"command": "cd /workspace && cat > src/buffer.rs <<'RSEOF'
//! A tiny terminal cell buffer plus a diffing renderer that produces the same
//! escape sequences as ratatui's crossterm backend.

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Color {
    Reset,
    Indexed(u8),
}

pub const BOLD: u16 = 1 << 0;
pub const DIM: u16 = 1 << 1;
pub const ITALIC: u16 = 1 << 2;
pub const UNDERLINED: u16 = 1 << 3;
pub const REVERSED: u16 = 1 << 6;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Style {
    pub fg: Color,
    pub bg: Color,
    pub mods: u16,
}

pub const DEFAULT: Style = Style { fg: Color::Reset, bg: Color::Reset, mods: 0 };

pub const fn fg_indexed(n: u8) -> Style {
    Style { fg: Color::Indexed(n), bg: Color::Reset, mods: 0 }
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub struct Cell {
    pub ch: char,
    pub st: Style,
}

pub const BLANK: Cell = Cell { ch: ' ', st: DEFAULT };

pub struct Buffer {
    pub w: u16,
    pub h: u16,
    pub cells: Vec<Cell>,
}

impl Buffer {
    pub fn new(w: u16, h: u16) -> Buffer {
        let n = w as usize * h as usize;
        Buffer { w, h, cells: vec![BLANK; n] }
    }
    pub fn reset(&mut self) {
        for c in self.cells.iter_mut() {
            *c = BLANK;
        }
    }
    pub fn resize(&mut self, w: u16, h: u16) {
        let n = w as usize * h as usize;
        self.w = w;
        self.h = h;
        self.cells.resize(n, BLANK);
        self.reset();
    }
    #[inline]
    pub fn set(&mut self, x: u16, y: u16, ch: char, st: Style) {
        if x >= self.w || y >= self.h {
            return;
        }
        let i = y as usize * self.w as usize + x as usize;
        self.cells[i] = Cell { ch, st };
    }
    #[inline]
    pub fn get(&self, x: u16, y: u16) -> Cell {
        if x >= self.w || y >= self.h {
            return BLANK;
        }
        self.cells[y as usize * self.w as usize + x as usize]
    }
}

fn color_code(c: Color, fg: bool) -> String {
    match c {
        Color::Reset => {
            if fg {
                "\x1b[39m".to_string()
            } else {
                "\x1b[49m".to_string()
            }
        }
        Color::Indexed(n) => {
            if fg {
                format!("\x1b[38;5;{}m", n)
            } else {
                format!("\x1b[48;5;{}m", n)
            }
        }
    }
}

fn modifier_diff(from: u16, to: u16, out: &mut Vec<u8>) {
    let removed = from & !to;
    if removed & REVERSED != 0 {
        out.extend_from_slice(b"\x1b[27m");
    }
    if removed & BOLD != 0 {
        out.extend_from_slice(b"\x1b[22m");
        if to & DIM != 0 {
            out.extend_from_slice(b"\x1b[2m");
        }
    }
    if removed & ITALIC != 0 {
        out.extend_from_slice(b"\x1b[23m");
    }
    if removed & UNDERLINED != 0 {
        out.extend_from_slice(b"\x1b[24m");
    }
    if removed & DIM != 0 {
        out.extend_from_slice(b"\x1b[22m");
    }
    let added = to & !from;
    if added & REVERSED != 0 {
        out.extend_from_slice(b"\x1b[7m");
    }
    if added & BOLD != 0 {
        out.extend_from_slice(b"\x1b[1m");
    }
    if added & ITALIC != 0 {
        out.extend_from_slice(b"\x1b[3m");
    }
    if added & UNDERLINED != 0 {
        out.extend_from_slice(b"\x1b[4m");
    }
    if added & DIM != 0 {
        out.extend_from_slice(b"\x1b[2m");
    }
}

/// Renders frames to stdout, keeping the previous frame around so that only
/// the differences are written (exactly like ratatui does).
pub struct Screen {
    pub w: u16,
    pub h: u16,
    bufs: [Buffer; 2],
    current: usize,
    out: Vec<u8>,
}

impl Screen {
    pub fn new(w: u16, h: u16) -> Screen {
        Screen {
            w,
            h,
            bufs: [Buffer::new(w, h), Buffer::new(w, h)],
            current: 0,
            out: Vec::with_capacity(8192),
        }
    }

    pub fn buf(&mut self) -> &mut Buffer {
        &mut self.bufs[self.current]
    }

    /// Clear the physical screen and force a full redraw next frame.
    pub fn hard_clear(&mut self) {
        self.out.extend_from_slice(b"\x1b[2J");
        let other = 1 - self.current;
        self.bufs[other].reset();
    }

    pub fn resize(&mut self, w: u16, h: u16) {
        self.w = w;
        self.h = h;
        self.bufs[0].resize(w, h);
        self.bufs[1].resize(w, h);
        self.hard_clear();
    }

    fn emit_diff(&mut self) {
        let other = 1 - self.current;
        let w = self.w;
        let h = self.h;
        let cur: &Buffer = &self.bufs[self.current];
        let prev: &Buffer = &self.bufs[other];
        let mut fg = Color::Reset;
        let mut bg = Color::Reset;
        let mut mods: u16 = 0;
        let mut last: Option<(u16, u16)> = None;
        for y in 0..h {
            for x in 0..w {
                let i = y as usize * w as usize + x as usize;
                if cur.cells[i] == prev.cells[i] {
                    continue;
                }
                let cell = cur.cells[i];
                let adjacent = matches!(last, Some((lx, ly)) if x == lx + 1 && y == ly);
                if !adjacent {
                    let s = format!("\x1b[{};{}H", (y as u32 + 1) as u16, (x as u32 + 1) as u16);
                    self.out.extend_from_slice(s.as_bytes());
                }
                last = Some((x, y));
                if cell.st.mods != mods {
                    modifier_diff(mods, cell.st.mods, &mut self.out);
                    mods = cell.st.mods;
                }
