                        let s = color_code(cell.st.fg, true);
                        self.out.extend_from_slice(s.as_bytes());
                        fg = cell.st.fg;
                    }
                    if cell.st.bg != bg {
                        let s = color_code(cell.st.bg, false);
                        self.out.extend_from_slice(s.as_bytes());
                        bg = cell.st.bg;
                    }
                }
                let mut b = [0u8; 4];
                self.out
                    .extend_from_slice(cell.ch.encode_utf8(&mut b).as_bytes());
            }
        }
        self.out
            .extend_from_slice(b"\x1b[39m\x1b[49m\x1b[59m\x1b[0m");
    }

    /// Finish the frame: write the diff, swap buffers and place the cursor.
    pub fn flush(&mut self, cursor: Option<(u16, u16)>) -> std::io::Result<()> {
        self.emit_diff();
        match cursor {
            None => self.out.extend_from_slice(b"\x1b[?25l"),
            Some((x, y)) => {
                self.out.extend_from_slice(b"\x1b[?25h");
                let s = format!("\x1b[{};{}H", (y as u32 + 1) as u16, (x as u32 + 1) as u16);
                self.out.extend_from_slice(s.as_bytes());
            }
        }
        let data = std::mem::take(&mut self.out);
        crate::term::write_stdout(&data)?;
        let other = 1 - self.current;
        self.bufs[other].reset();
        self.current = other;
        Ok(())
    }
}
