//! A tiny terminal cell buffer plus a diffing renderer that produces the same
//! escape sequences as ratatui's crossterm backend.

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Color {
    Reset,
    Indexed(u8),
}

pub const BOLD: u16 = 1 << 0;
pub const DIM: u16 = 1 << 1;
pub const ITALIC: u16 = 1 << 2;
pub const UNDERLINED: u16 = 1 << 3;
pub const REVERSED: u16 = 1 << 6;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Style {
    pub fg: Color,
    pub bg: Color,
    pub mods: u16,
}

pub const DEFAULT: Style = Style { fg: Color::Reset, bg: Color::Reset, mods: 0 };

pub const fn fg_indexed(n: u8) -> Style {
    Style { fg: Color::Indexed(n), bg: Color::Reset, mods: 0 }
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub struct Cell {
    pub ch: char,
    pub st: Style,
}

pub const BLANK: Cell = Cell { ch: ' ', st: DEFAULT };

pub struct Buffer {
    pub w: u16,
    pub h: u16,
    pub cells: Vec<Cell>,
}

impl Buffer {
    pub fn new(w: u16, h: u16) -> Buffer {
        let n = w as usize * h as usize;
        Buffer { w, h, cells: vec![BLANK; n] }
    }
    pub fn reset(&mut self) {
        for c in self.cells.iter_mut() {
            *c = BLANK;
        }
    }
    pub fn resize(&mut self, w: u16, h: u16) {
        let n = w as usize * h as usize;
        self.w = w;
        self.h = h;
        self.cells.resize(n, BLANK);
        self.reset();
    }
    #[inline]
    pub fn set(&mut self, x: u16, y: u16, ch: char, st: Style) {
        if x >= self.w || y >= self.h {
            return;
        }
        let i = y as usize * self.w as usize + x as usize;
        self.cells[i] = Cell { ch, st };
    }
    #[inline]
    pub fn get(&self, x: u16, y: u16) -> Cell {
        if x >= self.w || y >= self.h {
            return BLANK;
        }
        self.cells[y as usize * self.w as usize + x as usize]
    }
}

fn color_code(c: Color, fg: bool) -> String {
    match c {
