//! ngram frequency tables and lesson source loading.

pub const BIGRAMS: &str = include_str!("data/bigrams.txt");
pub const TRIGRAMS: &str = include_str!("data/trigrams.txt");
pub const TETRAGRAMS: &str = include_str!("data/tetragrams.txt");
pub const WORDS: &str = include_str!("data/words.txt");

#[derive(Clone)]
pub struct Source {
    pub items: Vec<String>,
}

fn one_per_line(s: &str) -> Vec<String> {
    s.lines().map(|l| l.to_string()).collect()
}

pub fn build(n: &str) -> Source {
    let items = match n {
        "2" => one_per_line(BIGRAMS),
        "3" => one_per_line(TRIGRAMS),
        "4" => one_per_line(TETRAGRAMS),
        "w" => one_per_line(WORDS),
        path => comma_file(path),
    };
    Source { items }
}

fn comma_file(path: &str) -> Vec<String> {
    if !std::path::Path::new(path).is_file() {
        println!("File not found: {}", path);
        std::process::exit(1);
