//! Lesson state and progression.

use crate::ngrams::Source;
use crate::rng::Rng;
use std::time::Instant;

pub struct Lesson {
    pub num: usize,
    pub text: Vec<char>,
    pub typed: Vec<char>,
    pub start: Option<Instant>,
    pub total: usize,
    pub errors: usize,
}

impl Lesson {
    fn new(num: usize) -> Lesson {
        Lesson { num, text: Vec::new(), typed: Vec::new(), start: None, total: 0, errors: 0 }
    }
    pub fn is_empty(&self) -> bool {
        self.text.is_empty()
    }
    pub fn full(&self) -> bool {
        self.typed.len() >= self.text.len()
    }
    pub fn all_correct(&self) -> bool {
        if self.typed.len() != self.text.len() {
            return false;
        }
        for i in 0..self.text.len() {
            if self.typed[i] != self.text[i] {
                return false;
            }
        }
        true
    }
}

/// Everything the game needs to know; also holds the running statistics.
pub struct Game {
    pub lesson: Lesson,
    pub src: Source,
    pub top: usize,
    pub combi: usize,
    pub rep: usize,
    pub wpm_need: i64,
    pub acc_need: i64,
    pub ok: usize,
    pub bad: usize,
    pub wpm_sum: u64,
    pub acc_sum: u64,
    pub stats_n: usize,
    pub last_wpm: u64,
    pub last_acc: u64,
    rng: Rng,
}

impl Game {
    pub fn new(src: Source, top: usize, combi: usize, rep: usize, wpm: i64, acc: i64) -> Game {
        Game {
            lesson: Lesson::new(0),
            src,
            top,
            combi,
            rep,
            wpm_need: wpm,
            acc_need: acc,
            ok: 0,
            bad: 0,
            wpm_sum: 0,
            acc_sum: 0,
            stats_n: 0,
            last_wpm: 0,
            last_acc: 0,
            rng: Rng::new(),
        }
    }

    pub fn lesson_text(&self) -> String {
        self.lesson.text.iter().collect()
    }

    /// pick `combi` items from the top `top` and repeat each `rep` times
    fn generate_text(&mut self) -> String {
        let pool = self.src.items.len().min(self.top);
        let mut picks: Vec<&String> = Vec::with_capacity(self.combi);
        for _ in 0..self.combi {
            let idx = self.rng.below(pool);
            let it = self.src.items.get(idx).unwrap();
            picks.push(it);
        }
        let mut s = String::new();
        for _ in 0..self.rep {
            for p in picks.iter() {
                s.push_str(p);
                s.push(' ');
            }
        }
        s
    }

    pub fn next_lesson(&mut self) {
        let num = self.lesson.num + 1;
        let text = self.generate_text();
        self.lesson = Lesson::new(num);
        self.lesson.text = text.chars().collect();
    }

    /// called when the current lesson has been typed completely and correctly
    pub fn finish(&mut self) {
        let elapsed = match self.lesson.start {
            Some(t) => t.elapsed().as_secs_f64(),
            None => 0.0,
        };
        let ns = self.lesson.text.iter().filter(|c| **c != ' ').count();
        let words = ns as f64 / 5.0;
        let wpm = if elapsed > 0.0 {
            (words * 60.0 / elapsed) as u64
        } else {
            u64::MAX
        };
        let total = self.lesson.total;
        let acc = if total > 0 { (total - self.lesson.errors) * 100 / total } else { 0 };
        let success = wpm as i64 >= self.wpm_need && acc as i64 >= self.acc_need;
        if success {
            self.ok += 1;
        } else {
            self.bad += 1;
        }
        self.last_wpm = wpm;
        self.last_acc = acc as u64;
        self.wpm_sum += wpm;
        self.acc_sum += acc as u64;
        self.stats_n += 1;
        self.next_lesson();
    }

    pub fn avg_wpm(&self) -> u64 {
        if self.stats_n == 0 {
            0
        } else {
            self.wpm_sum / self.stats_n as u64
        }
    }
    pub fn avg_acc(&self) -> u64 {
        if self.stats_n == 0 {
            0
        } else {
            self.acc_sum / self.stats_n as u64
        }
    }

    /// handle a printable character; returns true when the lesson changed
    pub fn on_char(&mut self, c: char) -> bool {
        if self.lesson.is_empty() {
            return false;
        }
        if self.lesson.full() {
            return false;
        }
        if self.lesson.start.is_none() {
            self.lesson.start = Some(Instant::now());
        }
        self.lesson.total += 1;
        let expected = self.lesson.text[self.lesson.typed.len()];
        let ok = c == expected;
        if !ok {
            self.lesson.errors += 1;
        }
        self.lesson.typed.push(c);
        if self.lesson.all_correct() {
            self.finish();
            return true;
        }
        false
    }

    pub fn on_backspace(&mut self) {
        if self.lesson.is_empty() {
            return;
        }
        if !self.lesson.typed.is_empty() {
            self.lesson.typed.pop();
            self.lesson.total += 1;
        }
    }
}
