        out.push(format!("  \u{2502}{}", keys_row(lay, 2)));
        out.push(format!("  \u{2514}{}", bottom_join(lay)));
    }
    out
}

fn keys_row(lay: &Layout, r: usize) -> String {
    let mut s = String::new();
    for (i, c) in lay.rows[r].chars().enumerate() {
        if i > 0 {
            s.push('\u{2502}');
        }
        s.push(' ');
        s.push(c);
        s.push(' ');
    }
    s.push('\u{2502}');
    s
}

fn mid_join(lay: &Layout, r: usize) -> String {
    // separator under row r: └┬──┴┬──┴...┬──┘
    let n = lay.rows[r].chars().count();
    let mut s = String::from("\u{2514}");
    for i in 0..n {
        if i > 0 {
            s.push('\u{2500}');
        }
        s.push('\u{252c}');
        s.push('\u{2500}');
        s.push('\u{2500}');
        if i == n - 1 {
            s.pop();
            s.push('\u{2534}');
            s.push('\u{2500}');
        }
    }
    s.push('\u{2518}');
    s
}

fn bottom_join(lay: &Layout) -> String {
    let n = lay.rows[2].chars().count();
    let mut s = String::from("\u{2500}\u{2500}\u{2500}");
    for i in 0..n {
        if i == 0 {
            continue;
        }
        s.push('\u{2500}');
        s.push('\u{2500}');
        s.push('\u{2500}');
        s.push('\u{2534}');
    }
    s.pop();
    s.push('\u{2518}');
    s
}

fn row_line(lay: &Layout, r: usize) -> String {
    let mut s = String::from("\u{2502}");
    for i in 0..12 {
        let c = lay.rows[r].chars().nth(i).unwrap_or('\u{25b3}');
        s.push(' ');
        s.push(c);
        s.push(' ');
        s.push('\u{2502}');
    }
    s
}

pub struct Ui {
    pub show_ortho: bool,
    pub nokb: bool,
    pub cat: bool,
    pub lay_in: &'static Layout,
    pub lay_out: &'static Layout,
}

impl Ui {
    pub fn draw(&self, scr: &mut Screen, g: &Game, w: u16, h: u16) -> Option<(u16, u16)> {
        let show_kb = !self.nokb;
        let box_h = if show_kb { BOX_H_KB } else { BOX_H_NOKB };
        if w < BOX_W || h < box_h {
            self.draw_resize(scr, w);
            return None;
        }
        let buf = scr.buf();
        // outer border
        for x in 0..BOX_W {
            buf.set(x, 0, '\u{2500}', DEFAULT);
            buf.set(x, box_h - 1, '\u{2500}', DEFAULT);
        }
        buf.set(0, 0, '\u{250c}', DEFAULT);
        buf.set(BOX_W - 1, 0, '\u{256e}', DEFAULT);
        buf.set(0, box_h - 1, '\u{2570}', DEFAULT);
        buf.set(BOX_W - 1, box_h - 1, '\u{256f}', DEFAULT);
        for y in 1..box_h - 1 {
            buf.set(0, y, '\u{2502}', DEFAULT);
            buf.set(BOX_W - 1, y, '\u{2502}', DEFAULT);
        }
        // separators
        for sy in [2usize, 4usize, (box_h - 4) as usize] {
            for x in 1..BOX_W - 1 {
                buf.set(x as u16, sy as u16, '\u{2500}', DEFAULT);
            }
        }
        // title, right aligned
        let title_len = 11usize;
        let tx = BOX_W - 1 - title_len as u16;
        for (i, c) in "Quit ".chars().enumerate() {
            buf.set(tx + i as u16, 1, c, DEFAULT);
        }
        for (i, c) in "<esc> ".chars().enumerate() {
            buf.set(tx + 5 + i as u16, 1, c, Style { mods: BOLD, fg: Color::Indexed(4), bg: Color::Reset });
        }
        // header line
        let hdr1: Vec<char> = "               ngrrram!".chars().collect();
        let hdr2: Vec<char> = "   by winterveil".chars().collect();
        let hdr_len = hdr1.len() + hdr2.len();
        let hx = 1 + centered_x(77, hdr_len);
        for (i, c) in hdr1.iter().enumerate() {
            buf.set(hx + i as u16, 1, *c, Style { mods: BOLD, ..DEFAULT });
        }
        for (i, c) in hdr2.iter().enumerate() {
            buf.set(hx + hdr1.len() as u16 + i as u16, 1, *c,
                    Style { mods: ITALIC, fg: Color::Indexed(7), bg: Color::Reset });
        }
        // lesson line
        let lesson: Vec<char> = "    Lesson #".chars()
            .chain(g.lesson.num.to_string().chars()).collect();
        for (i, c) in lesson.iter().enumerate() {
            buf.set(1 + i as u16, 3, *c, DEFAULT);
        }
        let cnt = format!("\u{2714}: {}, ", g.ok);
        let cnt2 = format!("\u{2718}: {}    ", g.bad);
        let cw = cnt.chars().count() + cnt2.chars().count();
        let cx = BOX_W - 1 - cw as u16;
        for (i, c) in cnt.chars().enumerate() {
            buf.set(cx + i as u16, 3, c, fg_indexed(2));
        }
        for (i, c) in cnt2.chars().enumerate() {
            buf.set(cx + cnt.chars().count() as u16 + i as u16, 3, c, fg_indexed(1));
        }
        // lesson text + echo
        let text: Vec<char> = g.lesson.text.clone();
        let typed: Vec<char> = g.lesson.typed.clone();
        let lt: String = text.iter().collect();
        let x0 = 1 + centered_x(77, text.len());
        let mut styled: Vec<(char, Style)> = Vec::new();
        for i in 0..text.len() {
            if i < typed.len() {
                if typed[i] == text[i] {
                    styled.push((text[i], Style { mods: BOLD, fg: Color::Indexed(2), bg: Color::Reset }));
                } else {
                    let ch = if text[i] == ' ' { '\u{2022}' } else { text[i] };
                    styled.push((ch, Style { mods: BOLD, fg: Color::Indexed(1), bg: Color::Reset }));
                }
            } else {
                styled.push((text[i], Style { mods: BOLD, ..DEFAULT }));
            }
        }
        for (i, (c, st)) in styled.iter().enumerate() {
            if x0 as usize + i < 78 {
                buf.set(x0 + i as u16, 6, *c, *st);
            }
        }
        let mut echo: Vec<(char, Style)> = Vec::new();
        for i in 0..text.len() {
            if i < typed.len() && typed[i] != ' ' && typed[i] != text[i] {
                echo.push((typed[i], Style { mods: ITALIC, fg: Color::Indexed(7), bg: Color::Reset }));
            } else {
                echo.push((' ', Style { mods: ITALIC, fg: Color::Indexed(7), bg: Color::Reset }));
            }
        }
        for (i, (c, st)) in echo.iter().enumerate() {
            if x0 as usize + i < 78 {
                buf.set(x0 + i as u16, 7, *c, *st);
            }
        }
        // stats
        let stat_y = box_h - 3;
        let line1 = format!("  need >= {:>3}WPM,   avg. ", g.wpm_need);
        let line2 = format!("{:>3}WPM", g.avg_wpm());
        let line3 = ",   last";
        let line4 = format!(" {:>3}WPM", g.last_wpm);
        self.stats_line(buf, stat_y, &line1, &line2, line3, &line4);
        let line1 = format!("  need >= {:>3}% Acc, avg. ", g.acc_need);
        let line2 = format!("{:>3}% Acc", g.avg_acc());
        let line3 = ", last";
        let line4 = format!(" {:>3}% Acc", g.last_acc);
        self.stats_line(buf, stat_y + 1, &line1, &line2, line3, &line4);
        // keyboard
        let mut cursor = None;
        if show_kb {
            let kx = if self.cat { 6u16 } else { 14u16 };
            let kw = if self.cat { 55u16 } else { 64u16 };
            let lines = kb_lines(self.lay_out, self.show_ortho);
            let st = fg_indexed(7);
            for (y, l) in lines.iter().enumerate() {
                let mut padded: String = l.clone();
                while padded.chars().count() < kw as usize {
                    padded.push(' ');
                }
                let mut cx = kx;
                for c in padded.chars() {
                    buf.set(cx, 8 + y as u16, c, st);
                    cx += 1;
                }
            }
        }
        if self.cat {
            let ch = box_h.min(17);
            let cat_h = if ch > 10 { ch - 10 } else { 0 };
            for (y, l) in layouts::CAT.iter().enumerate() {
                if y as u16 >= cat_h {
                    break;
                }
                let mut cx = 61u16;
                for c in l.chars() {
                    buf.set(cx, 10 + y as u16, c, DEFAULT);
                    cx += 1;
                }
            }
        }
        // cursor position: after the typed characters
        let len = text.len();
        let off = ((77usize).wrapping_sub(len)).wrapping_div(2);
        let cx = (1usize.wrapping_add(off).wrapping_add(typed.len())) as u16;
        cursor = Some((cx, 6u16));
        cursor
    }

    fn stats_line(&self, buf: &mut Buffer, y: u16, s1: &str, s2: &str, s3: &str, s4: &str) {
        let mut x = 1u16;
        for c in s1.chars() {
            buf.set(x, y, c, fg_indexed(7));
            x += 1;
        }
        for c in s2.chars() {
            buf.set(x, y, c, DEFAULT);
            x += 1;
        }
        for c in s3.chars() {
            buf.set(x, y, c, fg_indexed(7));
            x += 1;
        }
        for c in s4.chars() {
            buf.set(x, y, c, DEFAULT);
            x += 1;
        }
    }

    fn draw_resize(&self, scr: &mut Screen, w: u16) {
        let buf = scr.buf();
        let lines = [
            "Please resize your terminal to at least 80x20,",
            "or consider disabling the keyboard display with --nokb",
            "",
            " <esc> or <ctrl-c> to quit",
        ];
        for (y, l) in lines.iter().enumerate() {
            let n = l.chars().count();
            let x = (w / 2).saturating_sub((n as u16) / 2);
            for (i, c) in l.chars().enumerate() {
                buf.set(x + i as u16, y as u16, c, DEFAULT);
            }
        }
    }
}
