mod args;
mod buffer;
mod game;
mod layouts;
mod ngrams;
mod rng;
mod term;
mod ui;

use buffer::{Cell, Screen};
use std::io::Write;
use std::process::exit;
use std::time::Duration;

fn main() {
    let cfg = args::parse();

    let half = cfg.emu_in.is_empty() && cfg.emu_out.is_empty();
    let both = !cfg.emu_in.is_empty() && !cfg.emu_out.is_empty();
    if !half && !both {
        println!("You need to specify both emu_in and emu_out.");
        exit(1);
    }

    let src = ngrams::build(&cfg.n);
    let g = game::Game::new(
        src,
        cfg.top as usize,
        cfg.combi as usize,
        cfg.rep as usize,
        cfg.wpm,
        cfg.acc,
    );

    let lay_in = layouts::lookup(&cfg.emu_in);
    let lay_out = layouts::lookup(&cfg.emu_out);
    let ui = ui::Ui {
        show_ortho: cfg.show_ortho,
        nokb: cfg.nokb,
        cat: cfg.cat,
        lay_in,
        lay_out,
    };

    // terminal setup: alt screen first, then raw mode
    let _ = term::write_stdout(b"\x1b[?1049h");
    if let Err(e) = term::enable_raw_mode() {
        let _ = term::disable_raw_mode();
        let mut err = std::io::stderr();
        let _ = writeln!(err, "Error: {:?}", e);
        exit(1);
    }

    let (w0, h0) = term::size().unwrap_or((79, 19));
    let mut scr = Screen::new(w0, h0);
    let _ = term::write_stdout(b"\x1b[2J");
    let _ = scr.flush(None);

    let mut g = g;
    let mut last_size = (w0, h0);

    loop {
        // autoresize
        if let Ok((w, h)) = term::size() {
            if (w, h) != last_size {
                last_size = (w, h);
                scr.resize(w, h);
            }
        }
        let (w, h) = last_size;

        if g.lesson.is_empty() {
            g.next_lesson();
        }
        let cur = scr.cursor();
        let cursor = ui.draw(&mut scr, &g, w, h);
        let _ = scr.flush(cursor);
        let _ = cur;

        if term::poll_stdin(16) {
            let mut buf = [0u8; 1024];
            match term::read_stdin(&mut buf) {
                Ok(n) if n > 0 => {
                    let bytes = &buf[..n];
                    let more = n == buf.len();
                    if !handle_input(&mut g, bytes, more) {
                        break;
                    }
                }
                _ => {}
            }
        }
    }

    term::disable_raw_mode();
    let _ = term::write_stdout(b"\x1b[?1049l");
}

/// parse the raw bytes read from the tty and feed the game.
/// returns false when the program should quit.
fn handle_input(g: &mut game::Game, b: &[u8], _more: bool) -> bool {
    let mut i = 0usize;
    while i < b.len() {
        let c = b[i];
        match c {
            0x1b => {
                if i + 1 >= b.len() {
                    return false; // Esc quits
                }
                match b[i + 1] {
                    b'[' => {
                        // CSI sequence: skip to the final byte
                        let mut j = i + 2;
                        while j < b.len() && !(0x40..=0x7e).contains(&b[j]) {
                            j += 1;
                        }
                        if j >= b.len() {
                            i = b.len();
                            continue;
                        }
                        match b[j] {
                            b'3' if j + 1 < b.len() && b[j + 1] == b'~' => {}
                            _ => {}
                        }
                        i = j + 1;
                    }
                    b'O' => {
                        i += 3;
                    }
                    0x1b => {
                        return false;
                    }
                    _ => {
                        // Alt + something
                        let rest = &b[i + 1..];
                        match rest[0] {
                            b'\r' => {
                                g.on_char(' ');
                            }
                            0x7f => {
                                g.on_backspace();
                            }
                            0x08 => {
                                g.on_backspace();
                            }
                            _ => {
                                let s = decode_char(rest);
                                if let Some(ch) = s {
                                    if filter_char(ch) {
                                        g.on_char(ch);
                                    }
                                }
                            }
                        }
                        i += 1 + utf8_len(rest);
                    }
                }
            }
            b'\r' => {
                g.on_char(' ');
                i += 1;
            }
            b'\t' => {
                i += 1;
            }
            0x7f => {
                g.on_backspace();
                i += 1;
            }
            0x08 => {
                g.on_backspace();
                i += 1;
            }
            0x00 => {
                g.on_char(' ');
                i += 1;
            }
            c @ 0x01..=0x1a => {
                let ch = (c - 1 + b'a') as char;
                if filter_char(ch) {
                    g.on_char(ch);
                }
                i += 1;
            }
            c @ 0x1c..=0x1f => {
                let ch = (c - 0x1c + b'4') as char;
                if filter_char(ch) {
                    g.on_char(ch);
                }
                i += 1;
            }
            _ => {
                let len = utf8_len(&b[i..]);
                let s = std::str::from_utf8(&b[i..i + len]).ok();
                if let Some(s) = s {
                    if let Some(ch) = s.chars().next() {
                        if filter_char(ch) {
                            g.on_char(ch);
                        }
                    }
                }
                i += len.max(1);
            }
        }
    }
    true
}

fn decode_char(b: &[u8]) -> Option<char> {
    std::str::from_utf8(b).ok().and_then(|s| s.chars().next())
}

fn utf8_len(b: &[u8]) -> usize {
    if b.is_empty() {
        return 1;
    }
    let c = b[0];
    if c < 0x80 {
        1
    } else if c >> 5 == 0b110 {
        2
    } else if c >> 4 == 0b1110 {
        3
    } else if c >> 3 == 0b11110 {
        4
    } else {
        1
    }
}

fn filter_char(c: char) -> bool {
    c.is_alphabetic() || c == ' '
}
