        let mut bot = String::from("\u{2514}");
        for i in 0..12 {
            let last = i == 11;
            top.push_str("\u{2500}\u{2500}\u{2500}");
            mid.push_str("\u{2500}\u{2500}\u{2500}");
            bot.push_str("\u{2500}\u{2500}\u{2500}");
            top.push(if last { '\u{2510}' } else { '\u{252c}' });
            mid.push(if last { '\u{2524}' } else { '\u{253c}' });
            bot.push(if last { '\u{2518}' } else { '\u{2534}' });
        }
        out.push(top);
        out.push(row_line(lay, 0));
        out.push(mid.clone());
        out.push(row_line(lay, 1));
        out.push(mid);
        out.push(row_line(lay, 2));
        out.push(bot);
    } else {
        let top = format!("\u{250c}{}\u{2510}", "\u{2500}\u{2500}\u{2500}\u{252c}".repeat(11));
        out.push(top);
        out.push(format!("\u{2502}{}", keys_row(lay, 0)));
        out.push(mid_join(lay, 0));
        out.push(format!(" \u{2502}{}", keys_row(lay, 1)));
        out.push(mid_join(lay, 1));
        out.push(format!("  \u{2502}{}", keys_row(lay, 2)));
        out.push(format!("  \u{2514}{}", bottom_join(lay)));
    }
    out
}

fn keys_row(lay: &Layout, r: usize) -> String {
    let mut s = String::new();
    for (i, c) in lay.rows[r].chars().enumerate() {
        if i > 0 {
            s.push('\u{2502}');
        }
        s.push(' ');
        s.push(c);
        s.push(' ');
    }
    s.push('\u{2502}');
    s
}

fn mid_join(lay: &Layout, r: usize) -> String {
    // separator under row r: └┬──┴┬──┴...┬──┘
    let n = lay.rows[r].chars().count();
    let mut s = String::from("\u{2514}");
    for i in 0..n {
        if i > 0 {
            s.push('\u{2500}');
        }
        s.push('\u{252c}');
        s.push('\u{2500}');
        s.push('\u{2500}');
        if i == n - 1 {
            s.pop();
            s.push('\u{2534}');
            s.push('\u{2500}');
        }
    }
    s.push('\u{2518}');
    s
}

fn bottom_join(lay: &Layout) -> String {
    let n = lay.rows[2].chars().count();
    let mut s = String::from("\u{2500}\u{2500}\u{2500}");
    for i in 0..n {
        if i == 0 {
            continue;
        }
        s.push('\u{2500}');
        s.push('\u{2500}');
        s.push('\u{2500}');
        s.push('\u{2534}');
    }
    s.pop();
    s.push('\u{2518}');
    s
}

fn row_line(lay: &Layout, r: usize) -> String {
    let mut s = String::from("\u{2502}");
    for i in 0..12 {
        let c = lay.rows[r].chars().nth(i).unwrap_or('\u{25b3}');
        s.push(' ');
        s.push(c);
        s.push(' ');
        s.push('\u{2502}');
    }
    s
}

